from __future__ import annotations
import torch
import helion
import helion.language as hl


@helion.kernel(ignore_warnings=[helion.exc.TensorOperationInWrapper])
def carried2d_plus_fullslice(x: torch.Tensor, y: torch.Tensor):
    BT, V = x.shape
    bn = hl.register_block_size(V)
    bm = hl.register_block_size(BT)
    o_loss = torch.zeros([BT], dtype=torch.float32, device=x.device)
    o_max = torch.zeros([BT], dtype=torch.float32, device=x.device)
    for tb in hl.tile(BT, block_size=bm):
        acc = hl.zeros([tb, bn], dtype=torch.float32)
        for tv in hl.tile(V, block_size=bn):
            acc += x[tb, tv].to(torch.float32) * y[tb, tv].to(torch.float32)
        o_loss[tb] = acc.sum(-1)
        o_max[tb] = torch.amax(x[tb, :].to(torch.float32), -1)
    return o_loss, o_max


def make_args(BT: int = 8192, V: int = 4096, dtype=torch.bfloat16, device="cuda"):
    return (
        torch.randn(BT, V, device=device, dtype=dtype),
        torch.randn(BT, V, device=device, dtype=dtype),
    )

from __future__ import annotations
import torch
import helion
import helion.language as hl


@helion.kernel(ignore_warnings=[helion.exc.TensorOperationInWrapper])
def carried_3d_tile(x: torch.Tensor):
    BT, A, V = x.shape
    bn = hl.register_block_size(V)
    bm = hl.register_block_size(BT)
    out = torch.zeros([BT, A], dtype=torch.float32, device=x.device)
    for tb in hl.tile(BT, block_size=bm):
        acc = hl.zeros([tb, A, bn], dtype=torch.float32)
        for tv in hl.tile(V, block_size=bn):
            acc += x[tb, :, tv].to(torch.float32)
        out[tb, :] = acc.sum(-1)
    return out


def make_args(BT: int = 8192, A: int = 16, V: int = 4096, dtype=torch.bfloat16, device="cuda"):
    return (torch.randn(BT, A, V, device=device, dtype=dtype),)

from __future__ import annotations
import torch
import helion
import helion.language as hl


@helion.kernel(ignore_warnings=[helion.exc.TensorOperationInWrapper])
def c2_coresident_pair_then_lone_wide(x: torch.Tensor, g: torch.Tensor):
    BT, Ma, Na = x.shape
    Mg, _ = g.shape
    op = torch.empty([BT, Ma, Na], dtype=torch.float32, device=x.device)
    wide = torch.empty([Mg], dtype=torch.float32, device=g.device)
    for tb in hl.tile(BT, block_size=1):
        blk = x[tb, :, :].to(torch.float32)
        col = blk.sum(1)
        row = blk.sum(2)
        op[tb, :, :] = row[:, :, None] * col[:, None, :]
    for tm in hl.tile(Mg):
        wide[tm] = g[tm, :].to(torch.float32).sum(-1)
    return op, wide


def make_args(BT: int = 4096, Ma: int = 64, Na: int = 64, Mg: int = 4096, Nw: int = 32768, dtype=torch.float32, device="cuda"):
    return (
        torch.randn(BT, Ma, Na, device=device, dtype=dtype),
        torch.randn(Mg, Nw, device=device, dtype=dtype),
    )
